"""Exact-record report from one shared 5M tournament run."""
from pathlib import Path
from io import StringIO
import csv,json,html
import numpy as np
from plotly.offline import get_plotlyjs
ROOT=Path(__file__).resolve().parents[1]
def main():
 data=ROOT/'data/processed/v2';res=ROOT/'results/tournament';m=np.load(data/'model.npz');z=np.load(res/'aggregate.npz')
 payload={k:m[k].tolist() for k in ['names','counts','win','draw','W','D']}
 payload.update({k:z[k].tolist() for k in ['exposure','outcomes','opp_records','finals','paths','top_hist','totals','state_tournaments','mc_se','journey','state_placements','playoffs']})
 examples=np.load(res/'examples.npz');payload['examples']={k:examples[k].tolist() for k in ['opponents','results','ids']}
 payload['manifest']=json.loads((res/'manifest.json').read_text());payload['completion']=json.loads((res/'completion.json').read_text());payload['sources']=json.loads((data/'sources.json').read_text())
 options=''.join(f'<option value="{i}">{html.escape(n)}'+(' · categoría agregada' if n in ['Other','Unknown'] else '')+'</option>' for i,n in enumerate(payload['names']) if payload['counts'][i]>0)
 css='''*{box-sizing:border-box}body{margin:0;background:#f2f1ec;color:#203744;font:15px/1.65 Arial,sans-serif}main{max-width:1240px;margin:auto;padding:38px 24px 70px}h1{font-size:clamp(36px,5vw,62px);letter-spacing:-1.8px;line-height:1.1;margin:18px 0}h2{font-size:25px;line-height:1.2;margin:36px 0 18px}.eyebrow{font-size:12px;letter-spacing:2.8px;color:#146b80;font-weight:700}.lead{font-size:19px;color:#60727a}.controls{position:sticky;top:0;z-index:4;display:flex;flex-wrap:wrap;gap:18px;background:#fffdf8;border-bottom:3px solid #146b80;padding:16px 20px;box-shadow:0 5px 8px #00000008}label{display:grid;gap:4px;font-size:12px;font-weight:700}select,button{font:inherit;padding:9px 13px;border:1px solid #b6c8c8;border-radius:4px;background:white;color:#203744;max-width:100%}select{font-size:16px}button{cursor:pointer}button:hover{background:#e5eeeb}.presets{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.presets button{font-size:13px;padding:7px 11px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:13px;margin:20px 0}.card{background:#fffdf8;border-top:3px solid #146b80;padding:18px}.card strong{display:block;color:#146b80;font-size:29px}.card small{display:block;color:#61717b}.notice{background:#fff8e8;border-left:4px solid #d29f49;padding:16px 20px;margin:20px 0}.answer{font-size:20px;color:#146b80;margin:26px 0 10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.chart{min-width:0;background:#fffdf8;min-height:430px}.tablewrap{overflow:auto;max-height:650px;background:#fffdf8;margin:16px 0}table{border-collapse:collapse;font-size:13px;width:100%}th{text-align:left;position:sticky;top:0;background:#dfe9e6;padding:11px;white-space:nowrap}td{padding:10px 11px;border-bottom:1px solid #e6e9e3}tr:hover td{background:#f1f6f3}.subtle{font-size:13px;color:#61717b}.examples{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.example{background:#e1eeeb;padding:18px}.example strong{font-size:26px;display:block}.exports{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}a{color:#146b80}details{background:#fffdf8;padding:16px 20px;margin:22px 0}summary{font-weight:700;cursor:pointer}code{font-size:12px;background:#e8ece5;padding:3px}footer{margin-top:35px;color:#61717b;font-size:13px}@media(max-width:760px){main{padding:24px 14px}.controls{position:static}.grid,.examples{grid-template-columns:1fr}h1{letter-spacing:-1px}}'''
 body="""<div class="eyebrow">UN MISMO TORNEO · TODOS LOS JUGADORES</div><h1>El recorrido de cada mazo.</h1><p class="lead">5.000.000 de torneos completos de 110 jugadores.<br>7 rondas suizas, top 8 y eliminatorias hasta un campeón.</p><p class="subtle">Presencia: 671 plazas de 13 eventos presenciales recientes. Win rates: 1.703 matches de papel + 145 cruces online de top 8 publicados. Probabilidades condicionadas a este modelo; el suizo aproxima emparejamientos y no incluye ID ni drops.</p><div class="controls"><label>Arquetipo<select id="deck">OPTIONS</select></label><label>Qué jugadores quiero seguir<select id="group"><option value="top8">Llegaron al top 8</option><option value="miss">Quedaron fuera del top 8</option><option value="all">Todos los jugadores</option><option value="top4">Llegaron al top 4</option><option value="top2">Llegaron a la final</option><option value="champ">Ganaron el torneo</option></select></label><label>Qué encuentros del suizo<select id="outcome"><option value="all">Todos</option><option value="2">Ganados</option><option value="0">Perdidos</option><option value="1">Empatados</option></select></label></div><p id="headline" class="answer" aria-live="polite"></p><div id="odds" class="cards"></div><p class="subtle">Probabilidades globales por participación del arquetipo, calculadas sobre todos sus jugadores en la misma corrida. El filtro de recorrido selecciona qué historias observamos; no cambia estas probabilidades.</p><div id="groupInfo" class="notice"></div><h2>Los rivales que encontraron en el camino</h2><div id="journeyHeat" class="chart"></div><div class="grid"><div id="journeyResults" class="chart"></div><div id="journeyComparison" class="chart"></div></div><p class="subtle">El mapa de rivales y la comparación usan el filtro de encuentros ganados/perdidos/empatados. El gráfico de resultados muestra todos los resultados del grupo elegido. Son encuentros del suizo; las eliminatorias se muestran aparte.</p><h2>Detalle de una ronda del recorrido</h2><label>Ronda suiza<select id="historyRound"></select></label><div id="historyTable"></div><div id="roundNarrative" class="notice"></div><h2>Secuencias de victorias, derrotas y empates</h2><div id="journeyPaths"></div><p class="subtle">W = victoria, L = derrota, D = empate. Cada secuencia corresponde al suizo completo de un jugador del grupo elegido. Los rivales del mapa son distribuciones por ronda, no una secuencia de rivales inventada ni un recorrido individual representativo.</p><details open><summary>Ejemplos completos: rivales y resultado de cada partida</summary><p class="subtle">Recorridos reales de una muestra del inicio de la corrida, con todos los rivales y resultados del jugador. Son ejemplos ilustrativos, no los caminos más frecuentes. Se reconstruyeron reproduciendo exactamente el primer lote, sin cambiar sus números aleatorios.</p><div id="examplePaths"></div></details><h2>Las eliminatorias: del top 8 al campeonato</h2><div class="grid"><div id="playoffRivals" class="chart"></div><div id="playoffConversion" class="chart"></div></div><div id="playoffTable"></div><p class="subtle">Estas eliminatorias incluyen a todos los clasificados de tu arquetipo, independientemente del filtro de recorrido. Bracket por seeds: 1–8 / 4–5 / 2–7 / 3–6; ganadores adyacentes avanzan. No hay empates y se usa el WR decisivo de la matriz, sin modelar la ventaja de play/draw del seed.</p><details open><summary>Explorar los rivales posibles según ronda y récord exacto</summary><p>Esta consulta usa a todos los jugadores del mazo que llegaron al récord elegido, con independencia de si después hicieron top 8. Permite explorar cómo se desarrollan las mesas sin conocer el resultado futuro.</p><div class="controls"><label>Próxima ronda<select id="round"></select></label><label>Récord antes de jugar<select id="record"></select></label></div><p id="query" class="answer"></p><div id="stateCards" class="cards"></div><div class="grid"><div id="rivals" class="chart"></div><div id="enrichment" class="chart"></div></div><div id="ranking"></div><div class="exports"><button id="download">Descargar consulta CSV</button><button id="downloadAll">Descargar todos los récords de mi mazo CSV</button><button id="share">Copiar link a esta consulta</button><span id="shareStatus" aria-live="polite"></span></div><div id="heat" class="chart"></div><div id="oppRecords"></div><p class="subtle">Cada combinación W–L–D se registra por separado. No se fusionan récords que sumen los mismos puntos. Un torneo puede aportar varios jugadores del mismo arquetipo; encuentros y torneos tienen distintos denominadores. El IC Monte Carlo agrupa por lotes de torneos, sin medir incertidumbre de la matriz.</p></details><details><summary>Presencia inicial, matriz de win rate y muestras</summary><div id="meta"></div><div id="matrixInfo"></div><div id="wrMatrix" class="chart"></div><div id="matchups"></div></details><details><summary>Fuentes, supuestos y corrida reproducible</summary><div id="method"></div>SOURCES</details><footer>Corrida final: 5 millones de torneos compartidos por todos los arquetipos y filtros. Corte de datos: 19/10/2026. Los estudios anteriores se conservan como antecedentes y no alimentan estas probabilidades.</footer>""".replace('OPTIONS',options)
 def table(headers,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 events=list(csv.DictReader(StringIO((ROOT/'data/processed/events_accepted.csv').read_text())));online=list(csv.DictReader(StringIO((ROOT/'data/processed/online_sources_v2.csv').read_text())))
 sources='<h3>Presencia y matches presenciales</h3>'+table(['Evento','Fecha','Sede','Plazas','Fuente'],[[html.escape(e['name']),e['date'],html.escape(e['venue']),e['players'],f'<a href="{e["url"]}" target="_blank" rel="noreferrer">Melee ↗</a>'] for e in events if e['date']>='2026-09-20'])
 sources+='<h3>Matches online: eliminatorias publicadas</h3>'+table(['Evento','Fecha','Matches incluidos','Estado / fuente'],[[html.escape(e['event_id']),e['date'],e['matches'],f'<a href="{e["source"]}" target="_blank" rel="noreferrer">'+('MTGO ↗' if int(e['matches'])>0 else 'Excluido: sin datos primarios de partidas')+'</a>'] for e in online])
 body=body.replace('SOURCES',sources)
 js=(ROOT/'src/dashboard_tournament.js').read_text();text='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recorridos y resultados · Monte Carlo Pauper</title><style>'+css+'</style><script>'+get_plotlyjs()+'</script></head><body><main>'+body+'</main><script>const DATA='+json.dumps(payload,separators=(',',':')).replace('</','<\\/')+';</script><script>'+js+'</script></body></html>'
 target=ROOT/'reports/metagame_explorer.html';legacy=ROOT/'reports/legacy_explorer.html'
 if not legacy.exists() and target.exists():legacy.write_bytes(target.read_bytes())
 target.write_text(text);print('v2 report',len(text),'bytes',flush=True)
if __name__=='__main__':main()
